<script setup lang="ts">
// 标签管理页：/manage/tag（管理 tab 侧边栏）。
//
// 定位：把「标签词表治理」从 AI 审阅后台里拆出来独立成页。AI 审阅关心的是流水线跑得怎么样，
// 这里关心的是「一个概念有多少种叫法、挂了多少题、名字该由谁定」——受众与操作节奏都不同，
// 挤在一个 tab 里两个用途都做不深。
//
// 核心心智模型：**一个概念一行**（规范名 + 全部别名 + 实时挂题数），而不是一行一个标签。
// 本页最重要的交互是「展示名归属」徽章：
//   name_locked = true  → 人工设定，点击可交回 AI 管理（下次巡检重新评估最通用的叫法）
//   name_locked = false → AI 管理，点击提示「改个名字即可交给人工」（改名的自然结果就是锁定，
//                          不给用户额外造一个「锁定」开关）
import { computed, onMounted, ref, watch } from "vue";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips, ShowTextTipsError, ShowTextTipsInfo, ShowTextTipsSuccess } from "@/util/tips";
import {
  GetEnrichAliasList,
  GetEnrichTagHistory,
  GetEnrichTagManageList,
  GetEnrichTagProblems,
  GetEnrichTagSearch,
  GetEnrichTagSimilar,
  PostEnrichAliasAdd,
  PostEnrichAliasDelete,
  PostEnrichTagApprove,
  PostEnrichTagDeprecate,
  PostEnrichTagMerge,
  PostEnrichTagNormalizeBackfill,
  PostEnrichTagPin,
  PostEnrichTagReactivate,
  PostEnrichTagRename,
  PostEnrichTagUnlockName,
} from "@/apis/problem-enrichment";
import type { EnrichTagManageItem, TagChangeLog } from "@/types/problem-enrichment";
import type { TagAlias, TagProblemItem, TagSimilarPair } from "@/types/problem-enrichment";
import { TagStatus } from "@/types/problem-enrichment";
import { tagStatusText, tagStatusTheme, fmtTime } from "./enrich-common";
import { useBreakpoint } from "@/composables/useBreakpoint";
import { handleGotoProblem } from "@/util/router";

const { globalProperties } = useCurrentInstance();
const { isMobile } = useBreakpoint();

// 展示名长度上限：与后端 tagNameMaxRunes / tag.name varchar(20) 对齐
const TAG_NAME_MAX = 20;

// 每页条数：默认随断点（移动端一屏能扫的行更少），也允许用户自己改
const pageSize = ref(isMobile.value ? 20 : 50);

// ── 筛选与列表 ──
const loading = ref(false);
const list = ref<EnrichTagManageItem[]>([]);
const total = ref(0);
const page = ref(1);
// 默认「候选 + 正式」：已合并/已归档是历史态，要回溯时再勾上
const statusFilter = ref<number[]>([TagStatus.Candidate, TagStatus.Active]);
const keyword = ref("");
// 已提交的检索词：只有回车/点搜索才更新，避免每敲一个字都打一次后端
const submittedKeyword = ref("");

const statusOptions = [
  { label: "候选", value: TagStatus.Candidate },
  { label: "正式", value: TagStatus.Active },
  { label: "已合并", value: TagStatus.Merged },
  { label: "已归档", value: TagStatus.Deprecated },
];

const columns = [
  { colKey: "name", title: "规范名", minWidth: 180 },
  { colKey: "name_locked", title: "展示名归属", width: 130 },
  { colKey: "aliases", title: "别名", minWidth: 220 },
  { colKey: "status", title: "状态", width: 120 },
  { colKey: "problem_count", title: "挂题数", width: 90 },
  { colKey: "source", title: "来源", width: 90 },
  { colKey: "operation", title: "操作", width: 300, fixed: "right" as const },
];

// 当前页内的 id → 名字，用于把「已合并」行的 merged_to_id 显示成人能看懂的目标名
const nameById = computed(() => {
  const m = new Map<number, string>();
  list.value.forEach((t) => m.set(t.id, t.name));
  return m;
});

const mergedTargetName = (row: EnrichTagManageItem) => {
  if (row.merged_to_id == null) {
    return "";
  }
  return nameById.value.get(row.merged_to_id) ?? `#${row.merged_to_id}`;
};

const fetchList = async () => {
  loading.value = true;
  try {
    const res = await GetEnrichTagManageList(
      statusFilter.value.length > 0 ? statusFilter.value : null,
      submittedKeyword.value,
      page.value,
      pageSize.value
    );
    if (res.code === 0) {
      list.value = res.data?.list ?? [];
      total.value = res.data?.total ?? 0;
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "加载标签列表失败");
  } finally {
    loading.value = false;
  }
};

const onStatusChange = () => {
  page.value = 1;
  fetchList();
};

// 回车或点「搜索」才提交关键词
const onKeywordSubmit = () => {
  submittedKeyword.value = keyword.value.trim();
  page.value = 1;
  fetchList();
};

const onPageChange = () => {
  fetchList();
};

const onPageSizeChange = () => {
  page.value = 1;
  fetchList();
};

// 断点切换会改变每页条数：回到第一页重取，避免页码指到不存在的页
watch(isMobile, (mobile) => {
  pageSize.value = mobile ? 20 : 50;
  page.value = 1;
  fetchList();
});

// ── 疑似重复巡检（点击才跑：两两算相似度，不占首屏） ──
const similarVisible = ref(false);
const similarLoading = ref(false);
const similarPairs = ref<TagSimilarPair[]>([]);

const fetchSimilar = async () => {
  similarLoading.value = true;
  try {
    const res = await GetEnrichTagSimilar();
    if (res.code === 0) {
      // 后端已按相似度降序返回 Top 20
      similarPairs.value = res.data?.list ?? [];
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "加载疑似重复失败");
  } finally {
    similarLoading.value = false;
  }
};

const toggleSimilar = async () => {
  if (similarVisible.value) {
    similarVisible.value = false;
    return;
  }
  similarVisible.value = true;
  await fetchSimilar();
};

// ── 展示名归属：改名（= 锁定为人工设定）与交回 AI 管理 ──
const renameVisible = ref(false);
const renameTag = ref<EnrichTagManageItem | null>(null);
const renameName = ref("");
const renameSubmitting = ref(false);

const renameLength = computed(() => Array.from(renameName.value.trim()).length);
const renameValid = computed(() => renameLength.value > 0 && renameLength.value <= TAG_NAME_MAX);

const openRenameDialog = (tag: EnrichTagManageItem) => {
  renameTag.value = tag;
  // 预填现名：多数场景是微调，而不是从零起名
  renameName.value = tag.name;
  renameVisible.value = true;
};

const handleRenameSubmit = async () => {
  if (!renameTag.value || !renameValid.value) {
    return;
  }
  renameSubmitting.value = true;
  try {
    const res = await PostEnrichTagRename(renameTag.value.id, renameName.value.trim());
    if (res.code === 0) {
      ShowTextTipsSuccess(globalProperties, "展示名已更新，并锁定为人工设定");
      renameVisible.value = false;
      await refreshAfterMutate();
    } else {
      // 100126 重名 / 100127 名字非法：后端给的就是可读的业务提示
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "改名失败");
  } finally {
    renameSubmitting.value = false;
  }
};

const handleUnlockName = async (tag: EnrichTagManageItem) => {
  const res = await PostEnrichTagUnlockName(tag.id);
  if (res.code === 0) {
    ShowTextTipsSuccess(globalProperties, "展示名已交回 AI 管理");
    await refreshAfterMutate();
  } else {
    ShowErrorTips(globalProperties, res.code);
  }
};

// AI 管理态点击：没有「锁定」按钮——改名就是锁定，少一个要理解的概念
const hintAiManaged = () => {
  ShowTextTipsInfo(globalProperties, "当前展示名由 AI 管理：点「改名」定一个你认可的叫法即可交给人工");
};

// ── 合并（目标远程搜索，不限于当前页） ──
const mergeVisible = ref(false);
const mergeSource = ref<{ id: number; name: string } | null>(null);
const mergeTargetId = ref<number | undefined>(undefined);
const mergeTargetOptions = ref<{ label: string; value: number }[]>([]);
const mergeSearching = ref(false);
const mergeSubmitting = ref(false);

const openMergeDialog = (tag: { id: number; name: string } | null) => {
  if (!tag) {
    return;
  }
  mergeSource.value = tag;
  mergeTargetId.value = undefined;
  mergeTargetOptions.value = [];
  mergeVisible.value = true;
  searchMergeTarget("");
};

// 从疑似重复对直达合并对话框：左词并入右词（方向可在下拉里自行调整）
const openMergeFromSimilar = (pair: TagSimilarPair) => {
  mergeSource.value = { id: pair.left_id, name: pair.left_name };
  mergeTargetId.value = pair.right_id;
  mergeTargetOptions.value = [
    { label: `${pair.right_name}（挂题 ${pair.right_usage}）`, value: pair.right_id },
  ];
  mergeVisible.value = true;
};

const searchMergeTarget = async (kw: string) => {
  mergeSearching.value = true;
  try {
    // 只搜正式词：合并到候选词会让词表越并越乱
    const res = await GetEnrichTagSearch(kw, 20, [TagStatus.Active]);
    if (res.code === 0) {
      mergeTargetOptions.value = (res.data?.list ?? [])
        .filter((t) => t.id !== mergeSource.value?.id)
        .map((t) => ({ label: `${t.name}（挂题 ${t.usage_count}）`, value: t.id }));
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
  } finally {
    mergeSearching.value = false;
  }
};

const handleMergeSubmit = async () => {
  if (!mergeSource.value || !mergeTargetId.value) {
    return;
  }
  const sourceId = mergeSource.value.id;
  mergeSubmitting.value = true;
  try {
    const res = await PostEnrichTagMerge(sourceId, mergeTargetId.value);
    if (res.code === 0) {
      ShowTextTipsSuccess(globalProperties, "合并完成，历史关联已保留");
      mergeVisible.value = false;
      // 源标签已变成「已合并」，详情抽屉继续开着只会展示一个已经没意义的概念
      if (detailTag.value?.id === sourceId) {
        detailVisible.value = false;
        detailTag.value = null;
      }
      await refreshAfterMutate();
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "合并失败");
  } finally {
    mergeSubmitting.value = false;
  }
};

// ── 状态流转（批准 / 归档 / 恢复） ──
const handleApproveTag = async (tag: EnrichTagManageItem) => {
  const res = await PostEnrichTagApprove(tag.id);
  if (res.code === 0) {
    ShowTextTipsSuccess(globalProperties, "已批准为正式标签");
    await refreshAfterMutate();
  } else {
    ShowErrorTips(globalProperties, res.code);
  }
};

const handleDeprecateTag = async (tag: EnrichTagManageItem) => {
  const res = await PostEnrichTagDeprecate(tag.id);
  if (res.code === 0) {
    ShowTextTipsSuccess(globalProperties, "已归档");
    await refreshAfterMutate();
  } else {
    ShowErrorTips(globalProperties, res.code);
  }
};

const handleReactivateTag = async (tag: EnrichTagManageItem) => {
  const res = await PostEnrichTagReactivate(tag.id);
  if (res.code === 0) {
    ShowTextTipsSuccess(globalProperties, "已恢复为正式标签");
    await refreshAfterMutate();
  } else {
    ShowErrorTips(globalProperties, res.code);
  }
};

// ── 详情抽屉：别名管理 / 挂载题目 / 变更历史 ──
const detailVisible = ref(false);
const detailTag = ref<EnrichTagManageItem | null>(null);
const detailAliases = ref<TagAlias[]>([]);
const aliasLoading = ref(false);
const aliasInput = ref("");
const aliasSubmitting = ref(false);
const detailProblems = ref<TagProblemItem[]>([]);
const problemsLoading = ref(false);
const history = ref<TagChangeLog[]>([]);
const historyLoading = ref(false);

const openDetail = async (tag: EnrichTagManageItem) => {
  detailTag.value = tag;
  detailVisible.value = true;
  aliasInput.value = "";
  // 列表行已带别名，先铺上再拉最新，抽屉不必等网络才显示内容
  detailAliases.value = tag.aliases ?? [];
  detailProblems.value = [];
  history.value = [];
  await Promise.all([refreshDetailAliases(), fetchDetailProblems(tag.id), fetchHistory(tag.id)]);
};

const refreshDetailAliases = async () => {
  const tag = detailTag.value;
  if (!tag) {
    return;
  }
  aliasLoading.value = true;
  try {
    const res = await GetEnrichAliasList(tag.id);
    if (res.code === 0) {
      detailAliases.value = res.data ?? [];
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "加载别名失败");
  } finally {
    aliasLoading.value = false;
  }
};

const fetchDetailProblems = async (tagId: number) => {
  problemsLoading.value = true;
  try {
    const res = await GetEnrichTagProblems(tagId);
    if (res.code === 0) {
      detailProblems.value = res.data?.list ?? [];
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "加载挂载题目失败");
  } finally {
    problemsLoading.value = false;
  }
};

const fetchHistory = async (tagId: number) => {
  historyLoading.value = true;
  try {
    const res = await GetEnrichTagHistory(tagId, 50);
    if (res.code === 0) {
      // 后端已按新→旧返回
      history.value = res.data?.list ?? [];
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "加载变更历史失败");
  } finally {
    historyLoading.value = false;
  }
};

const handleAliasAdd = async () => {
  const tag = detailTag.value;
  const alias = aliasInput.value.trim();
  if (!tag || !alias) {
    return;
  }
  aliasSubmitting.value = true;
  try {
    const res = await PostEnrichAliasAdd(tag.id, alias);
    if (res.code === 0) {
      ShowTextTipsSuccess(globalProperties, "别名已登记");
      aliasInput.value = "";
      await refreshAfterMutate();
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "新增别名失败");
  } finally {
    aliasSubmitting.value = false;
  }
};

const handleAliasDelete = async (alias: TagAlias) => {
  const res = await PostEnrichAliasDelete(alias.id);
  if (res.code === 0) {
    ShowTextTipsSuccess(globalProperties, "别名已删除");
    await refreshAfterMutate();
  } else {
    ShowErrorTips(globalProperties, res.code);
  }
};

// 任一写操作之后：列表要新状态，抽屉要新别名与新历史（挂载题目不受这些操作影响，不重拉）
const refreshAfterMutate = async () => {
  await fetchList();
  const current = detailTag.value;
  if (!current) {
    return;
  }
  // 操作可能改变状态（如批准/归档/合并），用列表里的最新行覆盖抽屉头部
  const fresh = list.value.find((t) => t.id === current.id);
  if (fresh) {
    detailTag.value = fresh;
  }
  await refreshDetailAliases();
  await fetchHistory(current.id);
};

// ── 展示辅助 ──
// 别名超过 3 个时只铺前 3 个 + 「+N」，全部叫法放进 hover 提示
const aliasTooltip = (row: EnrichTagManageItem) => (row.aliases ?? []).map((a) => a.alias).join("、");

// 变更历史动作中文化（tag_change_log.action）
const actionText: Record<string, string> = {
  attach: "挂标签",
  detach: "撤标签",
  rename: "改名",
  merge: "合并",
  approve: "批准",
  deprecate: "归档",
  reactivate: "恢复",
  alias_add: "加别名",
  alias_delete: "删别名",
  lock: "锁定为人工",
  unlock: "交回 AI",
  reset: "重置",
};

const actionLabel = (action: string) => actionText[action] ?? action;

// 变更历史的写入者着色：谁改的必须一眼分得开，这是治理时最关键的信息
const historySourceText: Record<string, string> = { ai: "AI 审阅", human: "人工" };
const historySourceTheme: Record<string, "primary" | "success"> = { ai: "primary", human: "success" };

const gotoProblem = (key: string) => {
  if (key) {
    handleGotoProblem(key);
  }
};

// 重建归一化名（匹配键）：迁移脚本刻意没回填——SQL 复刻不了 Go 的归一化规则
// （全角转换 + 循环剥后缀），半吊子回填会让两套口径并存，比不回填更糟。
// 这里让管理员点一次，用 Go 规则精确重算全表。
const normalizeBackfilling = ref(false);const handleNormalizeBackfill = async () => {
  normalizeBackfilling.value = true;
  try {
    const res = await PostEnrichTagNormalizeBackfill();
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    const updated = res.data?.updated ?? 0;
    ShowTextTipsSuccess(
      globalProperties,
      updated > 0 ? `已重建 ${updated} 个标签的归一化名` : "归一化名已是最新，无需重建"
    );
    fetchList();
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  } finally {
    normalizeBackfilling.value = false;
  }
};

// 置顶 / 取消置顶：只影响标签云的展示顺序，不改变标签语义。
// 新置顶追加到置顶区末尾（取现有最大 order + 1），取消时归零——后端也会归零，
// 这里同步是为了列表立刻反映，不用等刷新。
const togglePin = async (row: EnrichTagManageItem) => {
  const nextPinned = !row.pinned;
  const maxOrder = list.value
    .filter((t) => t.pinned)
    .reduce((max, t) => Math.max(max, t.pin_order ?? 0), 0);
  const nextOrder = nextPinned ? maxOrder + 1 : 0;
  try {
    const res = await PostEnrichTagPin(row.id, nextPinned, nextOrder);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    row.pinned = nextPinned;
    row.pin_order = nextOrder;
    ShowTextTipsSuccess(
      globalProperties,
      nextPinned ? "已置顶：它会固定出现在标签云最前" : "已取消置顶"
    );
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  }
};

// 置顶区内上移 / 下移：与相邻的置顶标签**交换** pin_order。
//
// 用两次 SetTagPinned 而不是新开一个 swap 接口——置顶是低频操作，
// 省一个接口、少一处后端逻辑值得。两次调用之间若失败，两个标签会拿到相同的
// pin_order，此时排序由 update_time 兜底，不会出现「标签消失」这类硬故障。
const movePin = async (row: EnrichTagManageItem, delta: number) => {
  const pinnedList = list.value
    .filter((t) => t.pinned)
    .sort((a, b) => (a.pin_order ?? 0) - (b.pin_order ?? 0));
  const idx = pinnedList.findIndex((t) => t.id === row.id);
  const target = idx >= 0 ? pinnedList[idx + delta] : undefined;
  if (!target) {
    return;
  }
  const myOrder = row.pin_order ?? 0;
  const targetOrder = target.pin_order ?? 0;
  try {
    const first = await PostEnrichTagPin(row.id, true, targetOrder);
    if (first.code !== 0) {
      ShowErrorTips(globalProperties, first.code);
      return;
    }
    const second = await PostEnrichTagPin(target.id, true, myOrder);
    if (second.code !== 0) {
      ShowErrorTips(globalProperties, second.code);
      return;
    }
    row.pin_order = targetOrder;
    target.pin_order = myOrder;
    ShowTextTipsSuccess(globalProperties, delta < 0 ? "已上移" : "已下移");
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  }
};

onMounted(() => {
  fetchList();
});
</script>

<template>
  <div class="manage-tag">
    <!-- 疑似重复巡检入口：实时两两算相似度，点击才跑 -->
    <div class="mt-toolbar">
      <t-button variant="outline" @click="toggleSimilar">
        {{ similarVisible ? "收起疑似重复" : "疑似重复巡检" }}
      </t-button>
      <t-popconfirm
        content="用后端归一化规则重算全表归一化名（匹配键）。历史标签的归一化名尚未回填时，匹配会回退到「小写名」，改名或输入带后缀的说法仍可能产生重复词。幂等，可重复执行。"
        @confirm="handleNormalizeBackfill"
      >
        <t-button variant="outline" :loading="normalizeBackfilling">重建归一化名</t-button>
      </t-popconfirm>
      <span class="mt-muted">同一个概念的多种叫法会各自成行，巡检按归一化名相似度给出 Top 20 建议合并对</span>
    </div>

    <t-loading :loading="similarLoading" size="small">
      <div v-if="similarVisible" class="mt-similar">
        <div v-if="similarPairs.length === 0 && !similarLoading" class="mt-muted">暂无相似度达标的标签对</div>
        <div v-for="p in similarPairs" :key="`${p.left_id}-${p.right_id}`" class="mt-similar-row">
          <span class="mt-similar-pair">
